-- ============================================================================
-- B5 FOLLOW-ON W3 (Suite Full precision): gasprocessing capstone brief.
--
-- Plan of record: docs/graded-field-audit/FOLLOW-ON-PROGRAMME.md section 2 and
-- the section 1 Suite rows, decision D3 (owner approved D1 to D7 as
-- recommended, 2026-09-21). The Suite app the capstone is read in gains a
-- "Full precision" switch, off by default, that prints the graded quantities
-- at the precision they are graded to. The brief now says to switch it on.
--
-- ADVANCED
--   Fields read with the switch on: muFPerPsi, dropF, t2F, waterOutLbMMscf.
--   The Dew point tab rounds the chain to 1 decimal against tolerances of 5e-7
--   to 1e-4.
--   APPENDED: Read the figures in the Gas Processing Studio with its Full
--   precision switch on (at the top of the page): it prints them to the
--   precision this capstone grades, with no digit grouping.
--
-- WHAT DOES NOT MOVE. `fields` (every key, label, unit, expected and
-- tolerance, and their order), title, dataset, status and the row. The guard
-- requires `fields` to equal its post-W1 value exactly, before and after, so
-- no answer grades differently and no attempts guard is needed.
--
-- ORDER. Apply only once the Suite build carrying the W3 switch is live (the
-- brief names it). Runs after W1 (20261024*): refuses without it.
--
-- GUARDS. Each prompt must hold its post-W1 text (md5, rewritten) or its W3
-- text (left alone), with the exact fields. Anything else raises and the file
-- rolls back. Generated by docs/graded-field-audit/w3_capstones.py from
-- w3/gasprocessing.json. SAFE TO RE-RUN: a second run writes nothing.
-- ============================================================================

do $$
declare
  v_n        integer;
  v_count    integer;
  v_written  integer := 0;
  v_s0       text;
begin
  -- gasprocessing / advanced
  select count(*) into v_n from public.academy_capstones where app_slug = 'gasprocessing' and tier = 'advanced' and active;
  if v_n <> 1 then raise exception 'w3 gasprocessing refused: gasprocessing/advanced has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = 'c76210e77aa822c67406a46bd6320678' and fields = '[{"key": "dzdT", "tol": 5E-7, "unit": "per degR", "label": "Compressibility temperature derivative at the skid inlet", "expected": 0.0009683744638956019}, {"key": "muFPerPsi", "tol": 5E-7, "unit": "degF/psi", "label": "Joule-Thomson coefficient at that inlet", "expected": 0.06026080453221084}, {"key": "dropF", "tol": 0.0001, "unit": "degF", "label": "Cooling across the let-down, marched rather than taken in one step", "expected": 33.72690128392314}, {"key": "t2F", "tol": 0.0001, "unit": "degF", "label": "Temperature the gas reaches at the separator inlet", "expected": 53.27309871607686}, {"key": "waterInLbMMscf", "tol": 0.0001, "unit": "lb/MMscf", "label": "Water the gas carries at the skid inlet", "expected": 32.20884788270555}, {"key": "waterOutLbMMscf", "tol": 0.0001, "unit": "lb/MMscf", "label": "Water the gas can still hold at the cold spot", "expected": 23.519449233233914}]'::jsonb then 'old'
              when md5(prompt) = '4d8765fa51805132de4c470ece46ffd5' and fields = '[{"key": "dzdT", "tol": 5E-7, "unit": "per degR", "label": "Compressibility temperature derivative at the skid inlet", "expected": 0.0009683744638956019}, {"key": "muFPerPsi", "tol": 5E-7, "unit": "degF/psi", "label": "Joule-Thomson coefficient at that inlet", "expected": 0.06026080453221084}, {"key": "dropF", "tol": 0.0001, "unit": "degF", "label": "Cooling across the let-down, marched rather than taken in one step", "expected": 33.72690128392314}, {"key": "t2F", "tol": 0.0001, "unit": "degF", "label": "Temperature the gas reaches at the separator inlet", "expected": 53.27309871607686}, {"key": "waterInLbMMscf", "tol": 0.0001, "unit": "lb/MMscf", "label": "Water the gas carries at the skid inlet", "expected": 32.20884788270555}, {"key": "waterOutLbMMscf", "tol": 0.0001, "unit": "lb/MMscf", "label": "Water the gas can still hold at the cold spot", "expected": 23.519449233233914}]'::jsonb then 'new'
              else 'other' end
    into v_s0 from public.academy_capstones where app_slug = 'gasprocessing' and tier = 'advanced' and active;
  if v_s0 = 'other' then
    raise exception 'w3 gasprocessing refused: gasprocessing/advanced matches neither its post-W1 form (prompt md5 c76210e77aa822c67406a46bd6320678) nor its W3 form (prompt md5 4d8765fa51805132de4c470ece46ffd5), with the fields this file was generated against';
  end if;

  -- nothing to write: every row is already in its W3 form
  if v_s0 = 'new' then
    raise notice 'w3 gasprocessing: 0 of 1 row(s) written, all already applied';
    return;
  end if;

  -- W1 (20261024*) must be applied first: its rows are this file's base
  if not exists (select 1 from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
                  where c.app_slug = 'seismolord' and c.tier = 'intermediate' and c.active and f->>'key' = 'corr_zero_lag')
     or not exists (select 1 from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
                  where c.app_slug = 'mbal' and c.tier = 'beginner' and c.active and f->>'key' = 'eo_last_rb_stb')
     or not exists (select 1 from public.academy_capstones
                  where app_slug = 'basin' and tier = 'beginner' and active and prompt like 'Open book%') then
    raise exception 'w3 gasprocessing refused: W1 (20261024*) is not applied on this database; apply it first (/root/w1-apply/apply.sh apply --prod)';
  end if;

  if v_s0 = 'old' then
    update public.academy_capstones
       set prompt = 'ESCRAVOS, the dew point skid. Gas at 935 psia and 87 degF lets down across a choke to 405 psia into a low temperature separator. The gas gravity is 0.67 and its molar heat capacity is 10.2 Btu per lbmol degF. The let-down begins below the pressure at which this engine warns that its water chart correction is out of its stated band, so nothing reported here leans on a quantity held for the literature. Report six values: the compressibility temperature derivative at the inlet, the Joule-Thomson coefficient there, the cooling the let-down produces, the temperature the gas reaches, and the water it carries at the inlet and can still hold at the cold spot. The derivative per degR, the coefficient in degF a psi, temperatures in degF and water contents in lb a MMscf, all to six decimals. Read the figures in the Gas Processing Studio with its Full precision switch on (at the top of the page): it prints them to the precision this capstone grades, with no digit grouping.'
     where app_slug = 'gasprocessing' and tier = 'advanced' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w3 gasprocessing refused: gasprocessing/advanced updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = '4d8765fa51805132de4c470ece46ffd5' and fields = '[{"key": "dzdT", "tol": 5E-7, "unit": "per degR", "label": "Compressibility temperature derivative at the skid inlet", "expected": 0.0009683744638956019}, {"key": "muFPerPsi", "tol": 5E-7, "unit": "degF/psi", "label": "Joule-Thomson coefficient at that inlet", "expected": 0.06026080453221084}, {"key": "dropF", "tol": 0.0001, "unit": "degF", "label": "Cooling across the let-down, marched rather than taken in one step", "expected": 33.72690128392314}, {"key": "t2F", "tol": 0.0001, "unit": "degF", "label": "Temperature the gas reaches at the separator inlet", "expected": 53.27309871607686}, {"key": "waterInLbMMscf", "tol": 0.0001, "unit": "lb/MMscf", "label": "Water the gas carries at the skid inlet", "expected": 32.20884788270555}, {"key": "waterOutLbMMscf", "tol": 0.0001, "unit": "lb/MMscf", "label": "Water the gas can still hold at the cold spot", "expected": 23.519449233233914}]'::jsonb) from public.academy_capstones where app_slug = 'gasprocessing' and tier = 'advanced' and active) is not true then
    raise exception 'w3 gasprocessing refused: gasprocessing/advanced does not read back as its W3 form';
  end if;

  raise notice 'w3 gasprocessing: % of 1 row(s) written, % already applied', v_written, 1 - v_written;
end $$;
